from pathlib import Path
import re
p=Path('/tmp/index.html')
src=p.read_text(encoding='utf-8')
if '@supabase/supabase-js@2' not in src:
    src=src.replace('</head>', '\n  <script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>\n</head>', 1)
new_db='\n/* ===================== Supabase Realtime - almacenamiento central ===================== */\nconst SUPABASE_URL = "https://ppisbpcexufegkwnqyog.supabase.co";\nconst SUPABASE_KEY = "sb_publishable_bAgTrxjl6NkgpEazhmyu7A_1OrB4M6I";\nconst WORKSPACE_ID = "02979e85-9abc-44ec-9e2d-0d399be2a5eb";\n\nclass AppDB {\n  constructor(){\n    this.client=null;\n    this.versions=new Map();\n    this.cacheKey="mdd_supabase_offline_cache_v1";\n    this.queueKey="mdd_supabase_pending_ops_v1";\n    this.memoryCache={records:[],trash:[],meta:{}};\n    this.fallback=false;\n    this.connected=false;\n  }\n  key(store,id){return `${store}:${id}`}\n  itemId(store,obj){return store==="meta"?obj.key:obj.id}\n  _loadCache(){\n    try{\n      const raw=localStorage.getItem(this.cacheKey);\n      return raw?JSON.parse(raw):this.memoryCache;\n    }catch{return this.memoryCache}\n  }\n  _saveCache(data){\n    this.memoryCache=JSON.parse(JSON.stringify(data));\n    try{localStorage.setItem(this.cacheKey,JSON.stringify(data))}catch{}\n  }\n  _cacheStore(store,items){\n    const d=this._loadCache();\n    if(store==="meta")d.meta=Object.fromEntries(items.map(x=>[x.key,x.value]));\n    else d[store]=items;\n    this._saveCache(d);\n  }\n  _cachePut(store,obj){\n    const d=this._loadCache();\n    if(store==="meta"){d.meta=d.meta||{};d.meta[obj.key]=obj.value}\n    else{\n      d[store]=d[store]||[];\n      const i=d[store].findIndex(x=>x.id===obj.id);\n      if(i>=0)d[store][i]=obj;else d[store].push(obj);\n    }\n    this._saveCache(d);\n  }\n  _cacheDelete(store,key){\n    const d=this._loadCache();\n    if(store==="meta"){if(d.meta)delete d.meta[key]}\n    else d[store]=(d[store]||[]).filter(x=>x.id!==key);\n    this._saveCache(d);\n  }\n  _queue(){\n    try{return JSON.parse(localStorage.getItem(this.queueKey)||"[]")}catch{return []}\n  }\n  _saveQueue(q){try{localStorage.setItem(this.queueKey,JSON.stringify(q))}catch{}}\n  _enqueue(op){const q=this._queue();q.push(op);this._saveQueue(q)}\n  async init(){\n    if(!window.supabase?.createClient)throw new Error("No se pudo cargar el cliente de sincronización.");\n    this.client=window.supabase.createClient(SUPABASE_URL,SUPABASE_KEY,{\n      auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false},\n      realtime:{params:{eventsPerSecond:20}}\n    });\n    try{\n      const {error}=await this.client.from("mi_dia_a_dia_items").select("item_id").eq("workspace_id",WORKSPACE_ID).limit(1);\n      if(error)throw error;\n      this.connected=true;this.fallback=false;\n      await this.flushQueue();\n    }catch(e){\n      this.connected=false;this.fallback=true;\n      console.warn("Supabase temporalmente sin conexión; se usará caché offline.",e);\n    }\n    window.addEventListener("online",()=>this.flushQueue().catch(()=>{}));\n  }\n  async all(store){\n    if(this.client){\n      try{\n        const {data,error}=await this.client\n          .from("mi_dia_a_dia_items")\n          .select("item_id,payload,version,updated_at")\n          .eq("workspace_id",WORKSPACE_ID).eq("store",store)\n          .order("updated_at",{ascending:true});\n        if(error)throw error;\n        this.connected=true;this.fallback=false;\n        const rows=(data||[]).map(r=>{\n          this.versions.set(this.key(store,r.item_id),Number(r.version||1));\n          return r.payload||{};\n        });\n        this._cacheStore(store,rows);\n        return rows;\n      }catch(e){this.connected=false;this.fallback=true;console.warn("Lectura cloud falló; usando caché.",e)}\n    }\n    const d=this._loadCache();\n    if(store==="meta")return Object.entries(d.meta||{}).map(([key,value])=>({key,value}));\n    return d[store]||[];\n  }\n  async _remotePut(store,obj,allowQueue=true){\n    const id=this.itemId(store,obj);if(!id)throw new Error("Registro sin identificador.");\n    const k=this.key(store,id), expected=this.versions.has(k)?this.versions.get(k):null;\n    const args={p_workspace:WORKSPACE_ID,p_store:store,p_item_id:String(id),p_payload:obj,p_expected_version:expected};\n    try{\n      let {data,error}=await this.client.rpc("mdd_upsert_item",args);\n      if(error)throw error;\n      let row=Array.isArray(data)?data[0]:data;\n      if(row?.conflict){\n        const remote=row.current_payload||{}, remoteV=Number(row.current_version||1);\n        const localStamp=String(obj.updatedAt||obj.updated_at||""), remoteStamp=String(remote.updatedAt||remote.updated_at||"");\n        this.versions.set(k,remoteV);\n        if(remoteStamp && (!localStamp || remoteStamp>localStamp)){\n          Object.keys(obj).forEach(x=>delete obj[x]);Object.assign(obj,remote);\n          this._cachePut(store,obj);\n          return {conflict:true,remoteWon:true};\n        }\n        ({data,error}=await this.client.rpc("mdd_upsert_item",{...args,p_expected_version:remoteV}));\n        if(error)throw error;\n        row=Array.isArray(data)?data[0]:data;\n      }\n      if(row?.current_version)this.versions.set(k,Number(row.current_version));\n      this.connected=true;this.fallback=false;this._cachePut(store,obj);\n      return {conflict:false};\n    }catch(e){\n      this.connected=false;this.fallback=true;this._cachePut(store,obj);\n      if(allowQueue)this._enqueue({type:"put",store,obj});\n      throw e;\n    }\n  }\n  async put(store,obj){\n    try{return await this._remotePut(store,obj,true)}\n    catch(e){\n      try{state.storageWarning="Sin conexión: el cambio quedó en cola y se enviará automáticamente al reconectar."}catch{}\n      return {queued:true,error:e};\n    }\n  }\n  async _remoteDelete(store,key,allowQueue=true){\n    try{\n      const {error}=await this.client.from("mi_dia_a_dia_items").delete()\n        .eq("workspace_id",WORKSPACE_ID).eq("store",store).eq("item_id",String(key));\n      if(error)throw error;\n      this.versions.delete(this.key(store,key));this.connected=true;this.fallback=false;this._cacheDelete(store,key);\n    }catch(e){\n      this.connected=false;this.fallback=true;this._cacheDelete(store,key);\n      if(allowQueue)this._enqueue({type:"delete",store,key});\n      throw e;\n    }\n  }\n  async delete(store,key){try{await this._remoteDelete(store,key,true)}catch{}}\n  async clear(store){\n    try{\n      const {error}=await this.client.from("mi_dia_a_dia_items").delete().eq("workspace_id",WORKSPACE_ID).eq("store",store);\n      if(error)throw error;\n      [...this.versions.keys()].filter(k=>k.startsWith(store+":")).forEach(k=>this.versions.delete(k));\n      this._cacheStore(store,[]);\n    }catch(e){\n      const d=this._loadCache();if(store==="meta")d.meta={};else d[store]=[];this._saveCache(d);\n      this._enqueue({type:"clear",store});\n    }\n  }\n  async replaceAll(store,items){\n    await this.clear(store);\n    for(const item of items)await this.put(store,item);\n  }\n  async flushQueue(){\n    if(!this.client||!navigator.onLine)return;\n    const q=this._queue();if(!q.length)return;\n    const left=[];\n    for(const op of q){\n      try{\n        if(op.type==="put")await this._remotePut(op.store,op.obj,false);\n        else if(op.type==="delete")await this._remoteDelete(op.store,op.key,false);\n        else if(op.type==="clear"){\n          const {error}=await this.client.from("mi_dia_a_dia_items").delete().eq("workspace_id",WORKSPACE_ID).eq("store",op.store);\n          if(error)throw error;\n        }\n      }catch(e){left.push(op)}\n    }\n    this._saveQueue(left);\n    if(!left.length){this.connected=true;this.fallback=false;try{toast("Cambios offline sincronizados.")}catch{}}\n  }\n}\nconst db = new AppDB();\n'
src=re.sub(r'/\* ===================== IndexedDB ===================== \*/.*?const db = new AppDB\(\);', new_db.strip()+'\nconst db = new AppDB();', src, count=1, flags=re.S)
cloud_pattern=r'/\* ===================== Cloud sync shared link ===================== \*/.*?/\* ===================== Rendering helpers ===================== \*/'
shim='/* ===================== Cloud compatibility shim ===================== */\nfunction initCloud(){}\nasync function cloudPull(){return true}\nasync function cloudPush(){return true}\nfunction cloudEndpointFromURL(){return ""}\nfunction updateCloudUI(){\n  const b=document.getElementById("cloudBtn");\n  if(b){b.textContent="☁ Tiempo real";b.title="Datos centralizados en Supabase Realtime";}\n}\nfunction closeCloudOverlay(){\n  const el=document.getElementById("cloudOverlay");\n  if(el){el.classList.remove("open");el.setAttribute("aria-hidden","true");}\n}\nfunction openCloudOverlay(){\n  const el=document.getElementById("cloudOverlay");\n  if(el){el.classList.add("open");el.setAttribute("aria-hidden","false");}\n  const status=document.getElementById("cloudStatus");\n  if(status)status.textContent="Conectado a Supabase Realtime. Todos los usuarios de este enlace trabajan sobre el mismo espacio de datos.";\n}\n/* ===================== Rendering helpers ===================== */'
src=re.sub(cloud_pattern, shim, src, count=1, flags=re.S)
src=src.replace('  initCloud();\n  if(state.cloud.active){try{await cloudPull({silent:true,force:!!cloudEndpointFromURL()})}catch{}}\n','  initCloud();\n')
src=src.replace('  updateClock();setInterval(updateClock,30000);updateCloudUI();\n  document.addEventListener("visibilitychange",()=>{if(!document.hidden&&state.cloud.active)cloudPull({silent:true})});\n  window.addEventListener("focus",()=>{if(state.cloud.active)cloudPull({silent:true})});','  updateClock();setInterval(updateClock,30000);updateCloudUI();')
src=src.replace('<title>Mi Día a Día — Edición Profesional Compartida</title>','<title>Mi Día a Día — Tiempo Real</title>')
p.write_text(src,encoding='utf-8')
assert 'api.jsonstorage.net' not in src
assert 'indexedDB' not in src
assert '@supabase/supabase-js@2' in src
assert 'SUPABASE_URL' in src
